package com.gameaggregator.ledgerservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.ledgerservice.application.LedgerService;import com.gameaggregator.ledgerservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/ledger") public class LedgerController{final LedgerService s;public LedgerController(LedgerService s){this.s=s;}@PostMapping("/transactions")ApiResponse<RevenueTransaction> transaction(@Valid @RequestBody LedgerDtos.Transaction r){return ApiResponse.success(s.transaction(r));}@GetMapping("/transactions")ApiResponse<List<RevenueTransaction>> transactions(){return ApiResponse.success(s.transactions());}@PostMapping("/transactions/{id}/allocations")ApiResponse<RevenueAllocation> allocation(@PathVariable UUID id,@Valid @RequestBody LedgerDtos.Allocation r){return ApiResponse.success(s.allocation(id,r));}@PostMapping("/transactions/{id}/adjustments")ApiResponse<Adjustment> adjustment(@PathVariable UUID id,@Valid @RequestBody LedgerDtos.AdjustmentRequest r){return ApiResponse.success(s.adjustment(id,r));}@PostMapping("/settlements")ApiResponse<Settlement> settlement(@Valid @RequestBody LedgerDtos.SettlementRequest r){return ApiResponse.success(s.settlement(r));}}